});

function setupQuestionForm(form) {
  const rows = form.querySelector("[data-option-rows]");
  const template = form.querySelector("[data-option-template]");
  const addButton = form.querySelector("[data-add-option]");

  function numberRow(row, number) {
    const text = row.querySelector("[data-option-text]");
    const correct = row.querySelector("[data-option-correct]");
    const remove = row.querySelector("[data-remove-option]");
    text.name = `question[options][${number}][text]`;
    text.placeholder = `Option ${number}`;
    text.setAttribute("aria-label", `Option ${number}`);
    correct.name = `question[options][${number}][correct]`;
    correct.setAttribute("aria-label", `Option ${number} is correct`);
    row.querySelector("[data-correct-prefix]").textContent = `Option ${number} is `;
    remove.setAttribute("aria-label", `Remove option ${number}`);
  }

  addButton.addEventListener("click", () => {
    const row = template.content.firstElementChild.cloneNode(true);
    numberRow(row, rows.children.length + 1);
    rows.append(row);
    row.querySelector("[data-option-text]").focus();
  });

  rows.addEventListener("click", (event) => {
    const remove = event.target.closest("[data-remove-option]");
    if (!remove) return;

    const row = remove.closest("[data-option-row]");
    const nextField = row.nextElementSibling?.querySelector("[data-option-text]") || addButton;
    row.remove();
    Array.from(rows.children).forEach((child, index) => numberRow(child, index + 1));
    nextField.focus();
  });
}

function setupPreview(preview) {
  const questions = Array.from(preview.querySelectorAll("[data-preview-question]"));
  if (questions.length === 0) return;

  const screen = preview.querySelector("[data-preview-screen]");
  const result = preview.querySelector("[data-preview-result]");
  let index = 0;
  let score = 0;
  let answered = false;

  function showQuestion(focus = true) {
    answered = false;
    screen.replaceChildren(questions[index].content.cloneNode(true));
    if (focus) screen.querySelector("h1").focus();
  }

  function showScore() {
    screen.replaceChildren(result.content.cloneNode(true));
    const heading = screen.querySelector("[data-preview-score]");
    heading.textContent = `Score: ${score}/${questions.length}`;
    heading.focus();
  }

  function reveal(picked) {
    answered = true;
    const correct = picked.dataset.correct === "true";
    if (correct) score += 1;

    const options = screen.querySelector(".play-options");
    options.classList.add("is-locked", "is-revealed");
    picked.classList.add("is-picked");
    for (const option of options.querySelectorAll("[data-preview-answer]")) {
      option.disabled = true;
      if (option.dataset.correct === "true") {
        option.classList.add("is-correct");
        const mark = document.createElement("span");
        mark.className = "play-option__mark";
        mark.textContent = "✓ Correct";
        option.append(mark);
        option.setAttribute("aria-description", "Correct option");
      }
    }

    const feedback = screen.querySelector("[data-preview-feedback]");
    feedback.textContent = correct ? "Correct!" : "Wrong!";
    feedback.classList.add(correct ? "play-status--right" : "play-status--wrong");
    feedback.hidden = false;
    screen.querySelector("[data-preview-next]").hidden = false;
    feedback.focus();
  }

  screen.addEventListener("click", (event) => {
    const picked = event.target.closest("[data-preview-answer]");
    if (picked && !answered) reveal(picked);

    if (answered && event.target.closest("[data-preview-next]")) {
      index += 1;
      if (index < questions.length) showQuestion();
      else showScore();
    }
  });

  preview.querySelector("[data-preview-restart]").addEventListener("click", () => {
    index = 0;
    score = 0;
    showQuestion();
  });

  showQuestion(false);
}

document.querySelectorAll("[data-question-form]").forEach(setupQuestionForm);
document.querySelectorAll("[data-preview]").forEach(setupPreview);
