<% content_for :title, @game.title %>
<% content_for :live, "true" %>
<main class="screen live-stage" data-live-game="moderator"
      data-initial-state="<%= @state.to_json %>" data-state-url="<%= state_moderate_game_path(@game) %>"
      data-stream-token="<%= @game.signed_id(purpose: :live_updates) %>"
      data-advance-url="<%= advance_moderate_game_path(@game) %>"
      data-winners-url="<%= winners_moderate_game_path(@game) %>">
  <header class="screen__top">
    <span class="logo screen__logo"><span class="logo__mark" aria-hidden="true">?</span>Quizzy</span>
    <span class="live-stage__tag">Moderator · Live game</span>
  </header>
  <div class="screen__body">
    <% if @game.waiting? %>
      <section class="lobby" data-lobby>
        <div>
          <h1 class="lobby__title"><%= @game.title %></h1>
          <p class="lobby__join">Scan the code or go to</p>
          <p class="lobby__url" data-join-url><%= @join_url %></p>
          <p class="counter-pill" data-players role="status">Players: <%= @state.fetch(:players) %></p>
        </div>
        <div class="qr">
          <% qr = RQRCode::QRCode.new(@join_url).as_svg(use_path: true, viewbox: true, module_size: 1, offset: 4, fill: "fff") %>
          <%= image_tag "data:image/svg+xml;base64,#{Base64.strict_encode64(qr)}", alt: "QR code for the join link" %>
        </div>
      </section>
    <% end %>
    <section data-round aria-live="polite" hidden></section>
    <section class="live-results" data-ended <%= "hidden" unless @game.ended? %>>
